questions.question_text:
Which sketch shows $y=(x+3)^{2}(x-2)$?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{scope}[shift={(0,0)},scale=0.6]
\draw[->] (-5.6,0)--(3.6,0);
\draw[->] (0,-2.6)--(0,2.6);
\draw[thick,blue,<->,domain=-4.72:2.63,smooth,variable=\x] plot ({\x},{0.10*(\x+3)*(\x+3)*(\x-2)});
\node[below,font=\scriptsize] at (-3,-0.15) {$-3$};
\node[below,font=\scriptsize] at (2,-0.15) {$2$};
\node at (-5,2.1) {$A$};
\end{scope}
\begin{scope}[shift={(7.5,0)},scale=0.6]
\draw[->] (-4.6,0)--(4.6,0);
\draw[->] (0,-2.6)--(0,2.6);
\draw[thick,blue,<->,domain=-3.63:3.72,smooth,variable=\x] plot ({\x},{0.10*(\x+3)*(\x-2)*(\x-2)});
\node[below,font=\scriptsize] at (-3,-0.15) {$-3$};
\node[below,font=\scriptsize] at (2,-0.15) {$2$};
\node at (-4,2.1) {$B$};
\end{scope}
\begin{scope}[shift={(0,-4.2)},scale=0.6]
\draw[->] (-5.6,0)--(3.6,0);
\draw[->] (0,-2.6)--(0,2.6);
\draw[thick,blue,<->,domain=-4.72:2.63,smooth,variable=\x] plot ({\x},{-0.10*(\x+3)*(\x+3)*(\x-2)});
\node[below,font=\scriptsize] at (-3,-0.15) {$-3$};
\node[below,font=\scriptsize] at (2,-0.15) {$2$};
\node at (-5,2.1) {$C$};
\end{scope}
\begin{scope}[shift={(7.5,-4.2)},scale=0.6]
\draw[->] (-3.6,0)--(5.6,0);
\draw[->] (0,-2.6)--(0,2.6);
\draw[thick,blue,<->,domain=-2.63:4.72,smooth,variable=\x] plot ({\x},{0.10*(\x-3)*(\x-3)*(\x+2)});
\node[below,font=\scriptsize] at (-2,-0.15) {$-2$};
\node[below,font=\scriptsize] at (3,-0.15) {$3$};
\node at (-3,2.1) {$D$};
\end{scope}
\end{tikzpicture}
[/tikz]
